func (q *Queries) UpsertMealLog(ctx context.Context, arg UpsertMealLogParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertMealLog,
		arg.MealDate,
		arg.MealIndex,
		arg.Deadline,
		arg.Barcode,
		arg.Kcal,
		arg.Carbs,
		arg.Protein,
		arg.Fat,
		arg.Confidence,
		arg.Portion,
		arg.SharedMeal,
		arg.LoggedAt,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
